    if isinstance(o, dict):
        for k,v in o.items():
            if 'delivery' in k.lower() or 'maintenance' in k.lower():
                print(path+'/'+k, '=', v)
            find(v, path+'/'+k)
    elif isinstance(o, list):
        for i,v in enumerate(o):
            find(v, path+f'[{i}]')
find(d)
